    planning: "\u5927\u6D41\u91CF\u770B\u7684\u662F\u964C\u751F\u4EBA\uFF1A\u7B2C\u4E00\u79D2\u7559\u4F4F\u3001\u5B8C\u64AD\u3001\u4E92\u52A8\uFF0C\u88AB\u5E73\u53F0\u63A8\u7ED9\u4E0B\u4E00\u5C42\u4ECE\u6CA1\u5173\u6CE8\u8FC7\u4F60\u7684\u4EBA\u3002\u6240\u4EE5\u9009\u9898\u8981\u5927\u4F17\u4E00\u542C\u5C31\u61C2\u3001\u6709\u53CD\u5DEE\u6216\u5171\u9E23\uFF0C\u548C\u8D26\u53F7\u7C89\u4E1D\u591A\u5C11\u5173\u7CFB\u4E0D\u5927\u3002\u89C2\u70B9\u7C7B\u5185\u5BB9\u4E3B\u8981\u9760\u5DF2\u6709\u53D7\u4F17\uFF0C\u62FF\u4E0D\u5230\u5927\u6D41\u91CF\uFF0C\u4E0D\u4F5C\u4E3A\u6D41\u91CF\u578B\u7684\u4E3B\u6253\u3002\u9009\u9898\u8FC7\u4E09\u5173\uFF1A\u8986\u76D6\u591F\u4E0D\u591F\u5E7F\u3001\u6709\u6CA1\u6709\u660E\u786E\u4EF7\u503C\u3001\u662F\u4E0D\u662F\u6BD4\u964C\u751F\u4EBA\u591A\u4E00\u6B65\u8BA4\u77E5",
