// lib/creation-flow.ts
function creationScript(source, body) {
  if (source === "remix" && splitRemixPlans(body).plans.length > 1) return body;
  if (source === "script" || source === "storyboard") {
    const speech = body.replace(/\*\*/g, "").split("\n").map((line) => line.match(/^\s*(?:[-*>]\s*)?(?:台词(?:外音)?|口播)[：:]\s*(.+)/)?.[1]?.replace(/^["“‘]|["”’]$/g, "").trim()).filter((v) => Boolean(v));
    if (speech.length >= 2 && splitRemixPlans(body).plans.length <= 1) return speech.join("\n");
  }
  const name = source === "remix" ? /(?:口播全文|完整口播|完整脚本)/ : source === "review" ? /优化后的完整脚本/ : /(?:纯文字文案|口播全文|完整口播|完整脚本)/;
  if (!name) return body;
  const lines = body.split("\n");
  const start = lines.findIndex((line) => /^\s*#{1,4}\s+/.test(line) && name.test(line));
  if (start < 0) return body;
  const level = lines[start].match(/^\s*(#+)/)[1].length;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i++) {
    const next = lines[i].match(/^\s*(#{1,4})\s+(.*)$/);
    if (next && next[1].length <= level && !/^[^\p{L}\p{N}]*【/u.test(next[2])) {
      end = i;
      break;
    }
  }
  return lines.slice(start + 1, end).join("\n").replace(/\n\s*---\s*$/, "").trim() || body;
}

// lib/review-drift.ts
function normalize(text2) {
  return text2.replace(/(口播|台词|字幕|画面|旁白|镜头\s*\d*)\s*[：:]/g, "").replace(/【[^】]*】/g, "").replace(/[*#>\-|`~_\s]/g, "").replace(/[，。！？、；：,.!?;:"'“”‘’（）()\[\]「」『』《》<>…—]/g, "");
}
function sentencesOf(text2) {
  return text2.split(/[\n。！？!?]/).map((raw) => ({ raw: raw.replace(/^[\s*#>\-|]+/, "").trim(), key: normalize(raw) })).filter((s) => s.key.length >= 4);
}
var COPY_HEADING = /^#{1,4}\s*\d*\.?\s*纯文字文案/m;
function withoutCopySection(text2) {
  const m = COPY_HEADING.exec(text2);
  return m ? text2.slice(0, m.index) : text2;
}
function reviewDrift(draft, output) {
  const empty = { newSentences: [], unexplained: [] };
  const optimized = creationScript("review", output);
  if (!optimized || optimized === output || !draft.trim()) return empty;
  const explanation = normalize(withoutCopySection(output.replace(optimized, "")));
  const original = normalize(draft);
  const newSentences = sentencesOf(optimized).filter((s) => !original.includes(s.key));
  const unexplained = newSentences.filter((s) => !explanation.includes(s.key));
  return {
    newSentences: newSentences.map((s) => s.raw),
    unexplained: unexplained.map((s) => s.raw)
  };
}

